import numpy as np
from PIL import Image
def ball_row_span(t, kind='dough'):
    arr = np.asarray(Image.open(f'test_{t:.1f}.png').convert('RGB')).astype(int)
    front = arr[:, 0:1280]
    r,g,b = front[:,:,0], front[:,:,1], front[:,:,2]
    if kind=='dough':
        m = (r>150)&(g>100)&(g<230)&(b>80)&(b<210)&(r>g+15)&(r>b+35)
    else:
        m = (r>150)&(r-g>70)&(r-b>60)
    ys,xs = np.where(m)
    return xs.min(), xs.max(), ys.min(), ys.max(), len(xs)
